solution.javascript:
function compterJouets(jouets) {
  const compte = {};
  for (const jouet of jouets) {
    if (jouet in compte) {
      compte[jouet] = compte[jouet] + 1;
    } else {
      compte[jouet] = 1;
    }
  }
  return compte;
}

