solution.javascript:
function meilleursJouets(releves, k) {
  const totaux = {};
  for (const [etagere, jouet, quantite] of releves) {
    if (!(etagere in totaux)) {
      totaux[etagere] = {};
    }
    totaux[etagere][jouet] = (totaux[etagere][jouet] || 0) + quantite;
  }
  const resultat = {};
  for (const etagere in totaux) {
    const paires = Object.entries(totaux[etagere]);
    paires.sort((x, y) => {
      if (x[1] !== y[1]) {
        return y[1] - x[1];
      }
      return x[0] < y[0] ? -1 : x[0] > y[0] ? 1 : 0;
    });
    resultat[etagere] = paires.slice(0, k);
  }
  return resultat;
}

solution.python:
def meilleurs_jouets(releves, k):
    totaux = {}
    for etagere, jouet, quantite in releves:
        if etagere not in totaux:
            totaux[etagere] = {}
        totaux[etagere][jouet] = totaux[etagere].get(jouet, 0) + quantite
    resultat = {}
    for etagere in totaux:
        paires = [[jouet, total] for jouet, total in totaux[etagere].items()]
        paires.sort(key=lambda p: (-p[1], p[0]))
        resultat[etagere] = paires[:k]
    return resultat

